const clean=(v,n=2000)=>String(v??'').trim().slice(0,n);
const bool=v=>v===true||['1','true','yes','on'].includes(String(v??'').toLowerCase());
const num=(v,min=0,max=1e12)=>Math.max(min,Math.min(max,Number(v)||0));
const jsonParse=(v,f)=>{try{return JSON.parse(v??'')??f;}catch{return f;}};
