    const c=s.google,token=await googleRefreshToken(c),body={summary:event.title,description:event.notes||'',start:{dateTime:start.toISOString(),timeZone:event.timezone},end:{dateTime:end.toISOString(),timeZone:event.timezone},attendees:event.customerEmail?[{email:event.customerEmail,displayName:event.customerName||undefined}]:[],conferenceData:{createRequest:{requestId:`uc-${Date.now()}-${crypto.randomUUID().slice(0,8)}`,conferenceSolutionKey:{type:'hangoutsMeet'}}}};const r=await fetch(`https://www.googleapis.com/calendar/v3/calendars/${encodeURIComponent(c.calendarId||'primary')}/events?conferenceDataVersion=1&sendUpdates=all`,{method:'POST',headers:{authorization:`Bearer ${token}`,'content-type':'application/json'},body:JSON.stringify(body)}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d?.error?.message||'Google Calendar event could not be created.');return {id:d.id||'',url:d.hangoutLink||d.htmlLink||''};
