export async function marketingAnalytics(env,{start,end}={}){await ensureMarketingSchema(env);const today=new Date().toISOString().slice(0,10),from=/^\d{4}-\d{2}-\d{2}$/.test(start)?start:today.slice(0,8)+'01',to=/^\d{4}-\d{2}-\d{2}$/.test(end)?end:today;const r=await env.DB.prepare(`SELECT day,channel,SUM(impressions) impressions,SUM(clicks) clicks,SUM(leads) leads,SUM(conversions) conversions,SUM(spend_paise) spend_paise,SUM(revenue_paise) revenue_paise FROM marketing_daily_metrics WHERE day BETWEEN ? AND ? GROUP BY day,channel ORDER BY day,channel`).bind(from,to).all();const rows=r.results||[],totals=rows.reduce((a,x)=>{for(const k of ['impressions','clicks','leads','conversions','spend_paise','revenue_paise'])a[k]+=Number(x[k]||0);return a;},{impressions:0,clicks:0,leads:0,conversions:0,spend_paise:0,revenue_paise:0});return {start:from,end:to,rows,totals:{...totals,cpc_paise:totals.clicks?Math.round(totals.spend_paise/totals.clicks):0,cpm_paise:totals.impressions?Math.round(totals.spend_paise*1000/totals.impressions):0,cpa_paise:totals.conversions?Math.round(totals.spend_paise/totals.conversions):0,cac_paise:totals.conversions?Math.round(totals.spend_paise/totals.conversions):0,roas:totals.spend_paise?totals.revenue_paise/totals.spend_paise:0}};}
async function upsertMetric(env,row){await env.DB.prepare(`INSERT INTO marketing_daily_metrics(day,channel,campaign_id,impressions,clicks,leads,conversions,spend_paise,revenue_paise) VALUES(?,?,0,?,?,?,?,?,?) ON CONFLICT(day,channel,campaign_id) DO UPDATE SET impressions=excluded.impressions,clicks=excluded.clicks,leads=excluded.leads,conversions=excluded.conversions,spend_paise=excluded.spend_paise,revenue_paise=excluded.revenue_paise`).bind(row.day,row.channel,num(row.impressions),num(row.clicks),num(row.leads),num(row.conversions),num(row.spendPaise),num(row.revenuePaise)).run();}
export async function syncMarketingMetrics(env,{start,end}={}){
  await ensureMarketingSchema(env);const s=await getMarketingSettings(env),today=new Date().toISOString().slice(0,10),from=/^\d{4}-\d{2}-\d{2}$/.test(start)?start:today.slice(0,8)+'01',to=/^\d{4}-\d{2}-\d{2}$/.test(end)?end:today,results=[];
  if(s.googleAds.enabled&&s.googleAds.customerId){try{const token=await googleRefreshToken(s.googleAds),customer=clean(s.googleAds.customerId).replace(/\D/g,''),headers={authorization:`Bearer ${token}`,'developer-token':s.googleAds.developerToken,'content-type':'application/json'};if(s.googleAds.managerId)headers['login-customer-id']=clean(s.googleAds.managerId).replace(/\D/g,'');const query=`SELECT segments.date, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.conversions_value FROM customer WHERE segments.date BETWEEN '${from}' AND '${to}' ORDER BY segments.date`,r=await fetch(`https://googleads.googleapis.com/${s.googleAds.apiVersion||'v22'}/customers/${customer}/googleAds:searchStream`,{method:'POST',headers,body:JSON.stringify({query})}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d?.error?.message||'Google Ads reporting failed.');let count=0;for(const batch of Array.isArray(d)?d:[])for(const x of batch.results||[]){const m=x.metrics||{};await upsertMetric(env,{day:x.segments?.date,channel:'Google Ads',impressions:m.impressions,clicks:m.clicks,leads:0,conversions:m.conversions,spendPaise:Math.round(Number(m.costMicros||0)/10000),revenuePaise:Math.round(Number(m.conversionsValue||0)*100)});count++;}results.push({provider:'Google Ads',ok:true,days:count});}catch(e){results.push({provider:'Google Ads',ok:false,error:e.message});}}
  if(s.metaAds.enabled&&s.metaAds.adAccountId&&s.metaAds.accessToken){try{const account=clean(s.metaAds.adAccountId).replace(/^act_/,''),q=new URLSearchParams({fields:'date_start,impressions,clicks,spend,actions,action_values',time_increment:'1',time_range:JSON.stringify({since:from,until:to}),access_token:s.metaAds.accessToken,limit:'500'}),r=await fetch(`https://graph.facebook.com/v26.0/act_${encodeURIComponent(account)}/insights?${q}`),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d?.error?.message||'Meta Ads reporting failed.');let count=0;for(const x of d.data||[]){const actions=Object.fromEntries((x.actions||[]).map(a=>[a.action_type,Number(a.value||0)])),values=Object.fromEntries((x.action_values||[]).map(a=>[a.action_type,Number(a.value||0)])),conversions=actions.purchase||actions.omni_purchase||actions.offsite_conversion||0,revenue=values.purchase||values.omni_purchase||values.offsite_conversion||0;await upsertMetric(env,{day:x.date_start,channel:'Meta Ads',impressions:x.impressions,clicks:x.clicks,leads:actions.lead||0,conversions,spendPaise:Math.round(Number(x.spend||0)*100),revenuePaise:Math.round(revenue*100)});count++;}results.push({provider:'Meta Ads',ok:true,days:count});}catch(e){results.push({provider:'Meta Ads',ok:false,error:e.message});}}
  if(!results.some(x=>x.provider==='Google Ads'))results.push({provider:'Google Ads',ok:false,skipped:true,message:'Not enabled or reporting credentials are incomplete.'});
  if(!results.some(x=>x.provider==='Meta Ads'))results.push({provider:'Meta Ads',ok:false,skipped:true,message:'Not enabled or reporting credentials are incomplete.'});
  for(const [provider,config] of [['Pinterest Ads',s.pinterestAds],['X Ads',s.xAds],['Snapchat Ads',s.snapchatAds]])results.push({provider,ok:false,skipped:true,message:config?.enabled&&config?.verified?'Connection verified; direct reporting import is not enabled, so no figures were invented.':'Not enabled or not verified.'});
  const successful=results.filter(x=>x.ok);return {ok:successful.length>0,message:successful.length?`${successful.map(x=>`${x.provider}: ${x.days} daily row(s) synchronized`).join(' · ')}. Other rows below show their exact status.`:'No live reporting rows were imported. Review the provider-by-provider status below; existing saved figures were not changed.',results};
}
export async function heatmapReport(env,{start,end,path='/',device='all',mapType='heat'}={}){
  await ensureMarketingSchema(env);
  const today=new Date().toISOString().slice(0,10),from=start||today.slice(0,8)+'01',to=end||today,cleanPath=clean(path,300)||'/',type=['heat','scroll','attention'].includes(mapType)?mapType:'heat';
  const where=['day BETWEEN ? AND ?','path=?','map_type=?'],bind=[from,to,cleanPath,type],sessionWhere=['day BETWEEN ? AND ?','path=?'],sessionBind=[from,to,cleanPath];
  if(device&&device!=='all'){where.push('device=?');bind.push(clean(device,20));sessionWhere.push('device=?');sessionBind.push(clean(device,20));}
  const [r,sessions,top]=await Promise.all([
    env.DB.prepare(`SELECT x_bucket,y_bucket,element_key,SUM(event_count) event_count,SUM(duration_ms) duration_ms,SUM(visitors) visitors FROM heatmap_daily_cells WHERE ${where.join(' AND ')} GROUP BY x_bucket,y_bucket,element_key ORDER BY event_count DESC LIMIT 600`).bind(...bind).all(),
    env.DB.prepare(`SELECT max_scroll,COUNT(*) sessions,SUM(event_count) event_count,SUM(duration_ms) duration_ms FROM heatmap_daily_sessions WHERE ${sessionWhere.join(' AND ')} GROUP BY max_scroll ORDER BY max_scroll`).bind(...sessionBind).all(),
    env.DB.prepare(`SELECT element_key,SUM(event_count) event_count,SUM(duration_ms) duration_ms FROM heatmap_daily_cells WHERE day BETWEEN ? AND ? AND path=? AND map_type='heat'${device&&device!=='all'?' AND device=?':''} GROUP BY element_key ORDER BY event_count DESC LIMIT 20`).bind(from,to,cleanPath,...(device&&device!=='all'?[clean(device,20)]:[])).all()
  ]);
  const buckets=sessions.results||[],summary=buckets.reduce((a,x)=>{a.sessions+=Number(x.sessions||0);a.events+=Number(x.event_count||0);a.durationMs+=Number(x.duration_ms||0);a.weightedScroll+=Number(x.max_scroll||0)*Number(x.sessions||0);return a;},{sessions:0,events:0,durationMs:0,weightedScroll:0});
  const scrollReach=[];for(let depth=0;depth<=100;depth+=10){const reached=buckets.reduce((sum,x)=>sum+(Number(x.max_scroll||0)>=depth?Number(x.sessions||0):0),0);scrollReach.push({depth,reached,percent:summary.sessions?Math.round(reached/summary.sessions*100):0});}
  return {start:from,end:to,path:cleanPath,device,mapType:type,cells:r.results||[],summary:{visitors:summary.sessions,events:summary.events,durationMs:summary.durationMs,averageScroll:summary.sessions?Math.round(summary.weightedScroll/summary.sessions):0},scrollReach,topElements:top.results||[]};
}

