export async function listWebinars(env){await ensureMarketingSchema(env);const r=await env.DB.prepare(`SELECT w.*,(SELECT COUNT(*) FROM webinar_reminders r WHERE r.webinar_id=w.id AND r.status='pending') pending_reminders,(SELECT COUNT(*) FROM webinar_reminders r WHERE r.webinar_id=w.id AND r.channel='call' AND r.status='action_required') call_tasks_due FROM webinar_events w ORDER BY datetime(w.starts_at) DESC LIMIT 150`).all();return (r.results||[]).map(x=>({...x,reminders:jsonParse(x.reminder_plan_json,[])}));}
const CLASS_DAYS=['sun','mon','tue','wed','thu','fri','sat'];
function classDays(input){const values=Array.isArray(input)?input:jsonParse(input,[]);return [...new Set(values.map(x=>clean(x,3).toLowerCase()).filter(x=>CLASS_DAYS.includes(x)))];}
function indiaDateTime(date,time){const raw=`${clean(date,10)}T${clean(time,5)||'09:00'}:00+05:30`,value=new Date(raw);if(Number.isNaN(value.getTime()))throw new Error('Choose a valid start date and class time.');return value;}
