async function seedMemberReminders(env,memberId,start,days,plan,trialEnd=''){
  for(const day of days){const occurrence=nextClassOccurrence(start,day);if(!occurrence)continue;for(const reminder of plan){const sendAt=new Date(occurrence.getTime()-reminder.minutesBefore*60000);if(trialEnd&&occurrence>new Date(trialEnd))continue;await env.DB.prepare(`INSERT INTO webinar_member_reminders(member_id,channel,send_at,minutes_before,status,sent_at,error_text) VALUES(?,?,?,?,'pending',NULL,'') ON CONFLICT(member_id,channel,send_at) DO UPDATE SET minutes_before=excluded.minutes_before,status='pending',sent_at=NULL,error_text=''`).bind(memberId,reminder.channel,sendAt.toISOString(),reminder.minutesBefore).run();}}
}
