  await env.DB.prepare(`UPDATE webinar_members AS m SET status='past',membership_reason='Subscription cancelled or payment failed',moved_to_past_at=CURRENT_TIMESTAMP,updated_at=CURRENT_TIMESTAMP WHERE m.status='current' AND EXISTS(SELECT 1 FROM subscribers s WHERE ((m.customer_phone<>'' AND s.phone=m.customer_phone) OR (m.customer_email<>'' AND lower(s.email)=lower(m.customer_email))) AND lower(s.subscription_status) IN ('cancelled','canceled','failed','payment_failed','past_due')) AND NOT EXISTS(SELECT 1 FROM subscribers a WHERE ((m.customer_phone<>'' AND a.phone=m.customer_phone) OR (m.customer_email<>'' AND lower(a.email)=lower(m.customer_email))) AND lower(a.subscription_status) IN ('active','authenticated','paid','trialing'))`).run();
