async function processAdminMeetingReminders(env){const due=(await env.DB.prepare(`SELECT * FROM webinar_events WHERE status IN ('scheduled','rescheduled') AND datetime(starts_at)>=datetime('now','+14 minutes') AND datetime(starts_at)<datetime('now','+16 minutes') ORDER BY datetime(starts_at) LIMIT 20`).all()).results||[],sent=[];for(const event of due){const members=(await env.DB.prepare(`SELECT customer_name,customer_phone,customer_email,class_time,fees_paid_paise,last_payment_at,last_attendance_at FROM webinar_members WHERE event_type=? AND status='current' ORDER BY customer_name,id LIMIT 300`).bind(event.event_type).all().catch(()=>({results:[]}))).results||[],when=new Date(event.starts_at).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short',timeZone:event.timezone||'Asia/Kolkata'}),rows=members.map((member,index)=>`${index+1}. ${member.customer_name||'Name not recorded'} | ${member.customer_phone||'-'} | ${member.customer_email||'-'} | Fees: ${member.fees_paid_paise?`INR ${(Number(member.fees_paid_paise)/100).toFixed(2)}`:'Not recorded'} | Last payment: ${member.last_payment_at||'Not recorded'} | Last attendance: ${member.last_attendance_at||'Not recorded'}`),pdf=buildSimpleTextPdf({title:`${event.title} - Attendee List`,subtitle:`Scheduled ${when}`,lines:rows.length?rows:['No current members are recorded for this event type.']}),text=`Meeting starts in 15 minutes\nEvent: ${event.title}\nType: ${event.event_type}\nTime: ${when}\nAttendees: ${members.length}\nJoin: ${event.meeting_url||'No online joining link'}`;const result=await notifyAdmin(env,text,{subject:`Meeting in 15 minutes: ${event.title}`,eventType:'meeting_reminder',eventKey:`meeting-15-${event.id}-${event.starts_at}`,attachments:[{bytes:pdf,filename:`dropbeat-dance-studio-${event.event_type}-attendees.pdf`,contentType:'application/pdf'}]});sent.push({eventId:event.id,results:result});}return sent;}
const reminderIndiaDate=value=>{try{return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(value));}catch{return'';}};
async function nextRecurringClassStart(env,row,starts){
  let candidate=new Date(starts.getTime()+7*86400000);if(!Number(row.product_id||0))return candidate;
  const mapping=await env.DB.prepare("SELECT enabled,status FROM product_class_mappings WHERE product_id=? LIMIT 1").bind(Number(row.product_id)).first().catch(()=>null);if(!mapping||Number(mapping.enabled||0)!==1||mapping.status!=='active')return null;
  for(let attempt=0;attempt<20;attempt++){
    const sessionDate=reminderIndiaDate(candidate),override=await env.DB.prepare("SELECT starts_at,status FROM class_session_overrides WHERE mapping_id=? AND session_date=? LIMIT 1").bind(Number(row.product_id),sessionDate).first().catch(()=>null),status=clean(override?.status||'scheduled',30);
    if(['cancelled','holiday','leave'].includes(status)){candidate=new Date(candidate.getTime()+7*86400000);continue;}
    if(override?.starts_at&&!Number.isNaN(new Date(override.starts_at).getTime()))candidate=new Date(override.starts_at);
    return candidate;
  }
  return null;
}
async function processMemberClassReminders(env,{limit=40}={}){
  await refreshMemberStatuses(env);const rows=(await env.DB.prepare(`SELECT r.id reminder_id,r.channel reminder_channel,r.send_at reminder_send_at,r.minutes_before,m.* FROM webinar_member_reminders r JOIN webinar_members m ON m.id=r.member_id WHERE r.status='pending' AND m.status='current' AND datetime(r.send_at)<=CURRENT_TIMESTAMP ORDER BY datetime(r.send_at),r.id LIMIT ?`).bind(num(limit,1,100)||40).all()).results||[],out=[];
  for(const row of rows){const starts=new Date(new Date(row.reminder_send_at).getTime()+Number(row.minutes_before||0)*60000),title=row.event_type==='online_class'?'Online Class':row.event_type==='offline_class'?'Offline Class':'Demo / Webinar',notice={...row,title,starts_at:starts.toISOString(),timezone:row.timezone||'Asia/Kolkata'};try{if(row.reminder_channel==='call')await env.DB.prepare("UPDATE webinar_member_reminders SET status='action_required',error_text='Class reminder call is due.' WHERE id=?").bind(row.reminder_id).run();else{const results=await sendWebinarNotice(env,notice,'reminder'),failure=results.find(x=>x?.ok===false);if(failure)throw new Error(failure.error||'Class reminder could not be delivered.');await env.DB.prepare("UPDATE webinar_member_reminders SET status='sent',sent_at=CURRENT_TIMESTAMP,error_text='' WHERE id=?").bind(row.reminder_id).run();}
      const nextStart=await nextRecurringClassStart(env,row,starts),nextSend=nextStart?new Date(nextStart.getTime()-Number(row.minutes_before||0)*60000):null;if(nextStart&&(!row.trial_end_at||nextStart<=new Date(row.trial_end_at)))await env.DB.prepare(`INSERT OR IGNORE INTO webinar_member_reminders(member_id,channel,send_at,minutes_before) VALUES(?,?,?,?)`).bind(row.id,row.reminder_channel,nextSend.toISOString(),Number(row.minutes_before||0)).run();out.push({id:row.reminder_id,status:row.reminder_channel==='call'?'action_required':'sent'});
    }catch(e){await env.DB.prepare("UPDATE webinar_member_reminders SET status='failed',error_text=? WHERE id=?").bind(clean(e.message,500),row.reminder_id).run();out.push({id:row.reminder_id,status:'failed',error:e.message});}}
  return out;
}
export async function processWebinarReminders(env,{limit=40}={}){await ensureMarketingSchema(env);await ensureDanceStudioSchema(env);const r=await env.DB.prepare(`SELECT r.id reminder_id,r.channel reminder_channel,r.send_at reminder_send_at,w.* FROM webinar_reminders r JOIN webinar_events w ON w.id=r.webinar_id WHERE r.status='pending' AND datetime(r.send_at)<=CURRENT_TIMESTAMP AND w.status IN ('scheduled','rescheduled') ORDER BY datetime(r.send_at),r.id LIMIT ?`).bind(num(limit,1,100)||40).all(),out=[];for(const row of r.results||[]){try{if(row.reminder_channel==='call'){await env.DB.prepare("UPDATE webinar_reminders SET status='action_required',error_text='Admin follow-up call is due.' WHERE id=?").bind(row.reminder_id).run();out.push({id:row.reminder_id,status:'action_required',channel:'call'});continue;}const results=await sendWebinarNotice(env,row,'reminder'),failure=results.find(x=>x?.ok===false);if(failure)throw new Error(failure.error||`${row.reminder_channel} reminder could not be delivered.`);await env.DB.prepare("UPDATE webinar_reminders SET status='sent',sent_at=CURRENT_TIMESTAMP,error_text='' WHERE id=?").bind(row.reminder_id).run();out.push({id:row.reminder_id,status:'sent'});}catch(e){await env.DB.prepare("UPDATE webinar_reminders SET status='failed',error_text=? WHERE id=?").bind(clean(e.message,500),row.reminder_id).run();out.push({id:row.reminder_id,status:'failed',error:e.message});}}const [memberReminders,adminReminders]=await Promise.all([processMemberClassReminders(env,{limit}).catch(()=>[]),processAdminMeetingReminders(env).catch(()=>[])]);return {ok:true,processed:out.length+memberReminders.length,results:out,memberReminders,adminReminders};}
